const adminBase=[
 {name:'Kakamega Central',observed:184000,access:1.12,x:5,y:8,w:28,h:45},{name:'Bungoma East',observed:236000,access:.92,x:31,y:3,w:29,h:39},{name:'Busia North',observed:141000,access:1.05,x:61,y:8,w:33,h:39},{name:'Vihiga',observed:112000,access:1.18,x:10,y:51,w:26,h:38},{name:'Siaya East',observed:207000,access:.84,x:38,y:44,w:27,h:46},{name:'Homa Bay North',observed:254000,access:.76,x:66,y:49,w:30,h:43},{name:'Migori West',observed:198000,access:.81,x:20,y:75,w:31,h:22},{name:'Kisumu Rural',observed:167000,access:1.01,x:51,y:73,w:27,h:25}
];
const tech={
 'Modern beekeeping':{reach:18,beta:.58,sigma:.31,delta:.105,omega:.12,mu:.025,rho:.07},
 'Push–Pull Technology':{reach:24,beta:.82,sigma:.38,delta:.075,omega:.09,mu:.025,rho:.09},
 'Black Soldier Fly (BSF)':{reach:16,beta:.52,sigma:.34,delta:.12,omega:.11,mu:.025,rho:.08},
 'Fruit-fly IPM package':{reach:21,beta:.67,sigma:.42,delta:.10,omega:.10,mu:.025,rho:.08}
};
const state={technology:'Push–Pull Technology',target:30,deadline:36,eligibility:65,horizon:60,withdraw:36,metric:'tots',selected:0,sort:'tots',dir:-1,compartments:false};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],fmt=n=>Math.round(n).toLocaleString(),pct=n=>(n*100).toFixed(1)+'%';
function data(){const p=tech[state.technology],target=state.target/100,deadlineY=state.deadline/12;return adminBase.map((a,i)=>{const eligible=Math.round(a.observed*state.eligibility/100);const difficulty=(target/(1-target))*Math.pow(3/deadlineY,.72);let tots=Math.ceil(eligible/1000*difficulty*3.15/(p.reach/20*a.access));const cap=Math.ceil(eligible/1000*4.8);let reached=tots<=cap;if(!reached)tots=cap;const achieved=reached?target+Math.min(.025,.005*a.access):(target*(.72+.08*a.access));return {...a,eligible,tots,reached,achieved,intensity:tots/eligible*1000,adopters:Math.round(eligible*achieved),id:i}})}
function series(a,withdraw=null){const p=tech[state.technology],target=state.target/100,req=data()[a.id].tots,months=Math.max(state.deadline+24,(withdraw||0)+state.horizon),arr=[];let x=.012,A=.035,D=.01;for(let m=0;m<=months;m++){const active=withdraw===null||m<withdraw?1:0;const training=(req/Math.max(1,a.observed*state.eligibility/100))*p.reach*70*active*a.access;const U=Math.max(0,1-x-A-D);const dx=(p.sigma*A-p.delta*x-p.mu*x+p.rho*D)/12;const da=(training*U+p.beta*x*U-p.sigma*A-p.omega*A-p.mu*A)/12;const dd=(p.delta*x-(p.rho+p.mu)*D)/12;x=Math.max(0,Math.min(.9,x+dx));A=Math.max(0,Math.min(.9,A+da));D=Math.max(0,Math.min(.9,D+dd));arr.push({m,x,A,D,U:Math.max(0,1-x-A-D)})}return arr}
function render(){const rows=data(),a=rows[state.selected],total=rows.reduce((s,r)=>s+r.tots,0),eligible=rows.reduce((s,r)=>s+r.eligible,0),observed=rows.reduce((s,r)=>s+r.observed,0),ints=rows.map(r=>r.intensity).sort((x,y)=>x-y);$('#kpiTots').textContent=fmt(total);$('#kpiUnits').textContent=`${rows.filter(r=>r.reached).length} / ${rows.length}`;$('#kpiEligible').textContent=fmt(eligible);$('#kpiObserved').textContent=`${fmt(observed)} observed`;$('#kpiIntensity').textContent=((ints[3]+ints[4])/2).toFixed(2);$('#kpiGoal').textContent=`${state.target}% · ${state.deadline}m`;$('#targetOut').textContent=state.target+'%';$('#eligibilityOut').textContent=state.eligibility+'%';$('#withdrawOut').textContent=state.withdraw+' months';renderMap(rows);renderTable(rows);renderSelected(a);renderTrajectory(a);renderWithdrawal(a);renderParams()}
function renderMap(rows){const vals=rows.map(r=>state.metric==='tots'?r.tots:r.intensity),lo=Math.min(...vals),hi=Math.max(...vals);$('#map').innerHTML=rows.map((r,i)=>{const v=state.metric==='tots'?r.tots:r.intensity,t=(v-lo)/(hi-lo||1),light=88-t*42;return `<button class="region ${i===state.selected?'selected':''}" data-id="${i}" style="left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%;background:hsl(157 48% ${light}%)" title="${r.name}: ${state.metric==='tots'?r.tots:r.intensity.toFixed(2)}">${r.name.replace(' ','<br>')}</button>`}).join('');$$('.region').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.id;render()})}
function renderTable(rows){const sorted=[...rows].sort((a,b)=>{let x=a[state.sort],y=b[state.sort];if(typeof x==='string')return x.localeCompare(y)*state.dir;return (x-y)*state.dir});$('#adminRows').innerHTML=sorted.map(r=>`<tr data-id="${r.id}" class="${r.id===state.selected?'selected':''}"><td><strong>${r.name}</strong></td><td>${fmt(r.observed)}</td><td>${fmt(r.eligible)}</td><td>${r.tots}</td><td>${r.intensity.toFixed(2)}</td><td>${fmt(r.adopters)}</td><td>${pct(r.achieved)}</td><td><span class="status ${r.reached?'':'nr'}">${r.reached?'On target':'NR at cap'}</span></td></tr>`).join('');$$('#adminRows tr').forEach(tr=>tr.onclick=()=>{state.selected=+tr.dataset.id;render()})}
function renderSelected(a){$('#selectedName').textContent=a.name;$$('.selected-inline').forEach(x=>x.textContent=a.name);$('#selectedMeta').textContent=`${fmt(a.eligible)} eligible farmers · ${(a.access).toFixed(2)} access modifier`;$('#selectedTots').textContent=a.tots;$('#selectedIntensity').textContent=a.intensity.toFixed(2)+' / 1,000';$('#selectedAdopters').textContent=fmt(a.adopters);$('#temporalTots').textContent=a.tots+' ToTs';$('#temporalIntensity').textContent=a.intensity.toFixed(2)+' per 1,000 eligible farmers';$('#modelM').textContent=fmt(a.eligible);$('#accessMod').textContent=a.access.toFixed(2)}
function draw(svg,arr,opts={}){const W=900,H=390,m={l:58,r:22,t:26,b:45},maxM=arr.at(-1).m,x=v=>m.l+v/maxM*(W-m.l-m.r),y=v=>H-m.b-v/.6*(H-m.t-m.b),path=(key,start=0)=>arr.filter(d=>d.m>=start).map((d,i)=>(i?'L':'M')+x(d.m).toFixed(1)+','+y(d[key]).toFixed(1)).join(' ');let h='';for(let v=0;v<=.6;v+=.1)h+=`<line class="gridline" x1="${m.l}" x2="${W-m.r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="${m.l-10}" y="${y(v)+4}" text-anchor="end">${Math.round(v*100)}%</text>`;for(let mo=0;mo<=maxM;mo+=12)h+=`<text class="chart-label" x="${x(mo)}" y="${H-18}" text-anchor="middle">${mo}</text>`;h+=`<text class="chart-title" x="${m.l}" y="16">Active adoption X/M</text><text class="chart-label" x="${W/2}" y="${H-2}" text-anchor="middle">Months</text><line class="target-line" x1="${m.l}" x2="${W-m.r}" y1="${y(state.target/100)}" y2="${y(state.target/100)}"/><text class="chart-label" x="${W-m.r-4}" y="${y(state.target/100)-7}" text-anchor="end">${state.target}% target</text>`;if(opts.deadline){h+=`<line class="deadline-line" x1="${x(state.deadline)}" x2="${x(state.deadline)}" y1="${m.t}" y2="${H-m.b}"/><text class="chart-label" x="${x(state.deadline)+7}" y="${m.t+12}">Deadline</text>`}if(opts.withdraw){h+=`<line class="withdraw-line" x1="${x(state.withdraw)}" x2="${x(state.withdraw)}" y1="${m.t}" y2="${H-m.b}"/><path class="series" d="${path('x',0).split('L').slice(0,state.withdraw+1).join('L')}"/><path class="series post" d="${path('x',state.withdraw)}"/><text class="chart-label" x="${x(state.withdraw)+7}" y="${m.t+12}">ToTs withdrawn</text>`}else h+=`<path class="series" d="${path('x')}"/>`;if(state.compartments&&!opts.withdraw){[['U','#52738b'],['A','#f2b84b'],['D','#c56d65']].forEach(([k,c])=>h+=`<path class="compartment" stroke="${c}" d="${path(k)}"/>`)}svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=h}
function renderTrajectory(a){const arr=series(a),d=arr[state.deadline],reached=d.x>=state.target/100;draw($('#trajectoryChart'),arr,{deadline:true});$('#deadlineResult').textContent=reached?'Target reached':'Not reached within scenario';$('#deadlineText').textContent=`${pct(d.x)} active adoption at month ${state.deadline}.`}
function withdrawalStats(a,w=state.withdraw){const arr=series(a,w),after=arr.filter(d=>d.m>=w),at=arr[w].x,min=Math.min(...after.map(d=>d.x)),end=arr.at(-1).x,peak=Math.max(...after.map(d=>d.x)),maint=min>=state.target/100,p=tech[state.technology],ra=p.beta*p.sigma/((p.sigma+p.omega+p.mu)*(p.delta+p.mu)),eq=Math.max(0,Math.min(.8,(ra-1)/ra*(1-p.delta*.8)));return{arr,at,min,end,peak,maint,ra,eq}}
function renderWithdrawal(a){const s=withdrawalStats(a);draw($('#withdrawalChart'),s.arr,{withdraw:true});$('#atWithdrawal').textContent=pct(s.at);$('#postMin').textContent=pct(s.min);$('#postEnd').textContent=pct(s.end);$('#postPeak').textContent=pct(s.peak);const d=$('#maintenanceDecision');d.classList.toggle('warn',!s.maint);d.innerHTML=`<i></i><div><strong>${s.maint?'Target maintained':'Target not maintained'}</strong><span>${s.at>=state.target/100?'Reached':'Not reached'} at withdrawal; ${s.maint?'stays':'does not stay'} above target through follow-up.</span></div>`;$('#raValue').innerHTML=`R<sub>A</sub> = ${s.ra.toFixed(2)}`;$('#peerText').textContent=s.ra>1?'Peer diffusion is self-sustaining. This does not necessarily maintain the management target.':'Peer diffusion is not self-sustaining without ToT support.';$('#equilibrium').textContent='x* = '+pct(s.eq);let earliest='Not maintained';for(let w=6;w<=60;w+=6){if(withdrawalStats(a,w).maint){earliest=w+' months';break}}$('#earliest').textContent=earliest}
function renderParams(){const p=tech[state.technology],units={reach:'farmers/ToT/year',beta:'year⁻¹',sigma:'year⁻¹',delta:'year⁻¹',omega:'year⁻¹',mu:'year⁻¹',rho:'year⁻¹'},names={reach:'κ · ToT reach',beta:'β · peer diffusion',sigma:'σ · awareness → active',delta:'δ · active → dropout',omega:'ω · awareness loss',mu:'μ · population turnover',rho:'ρ · dropout → re-entry'};$('#parameterRows').innerHTML=Object.entries(p).map(([k,v])=>`<tr><td>${state.technology}</td><td><strong>${names[k]}</strong></td><td>${v}</td><td>${units[k]}</td><td><span class="status nr">Provisional scenario</span></td><td>${k==='reach'?'Evidence anchor / calibration target':'Calibration or sensitivity analysis required'}</td><td>${k==='beta'&&state.technology==='Push–Pull Technology'?'Strongest available peer-diffusion evidence':'Not an empirical estimate'}</td></tr>`).join('')}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
$('#csvBtn').onclick=()=>{const rows=data(),cols=['name','observed','eligible','tots','intensity','adopters','achieved','status'];download('ddr4d-admin2-requirements.csv',[cols.join(','),...rows.map(r=>[r.name,r.observed,r.eligible,r.tots,r.intensity.toFixed(3),r.adopters,r.achieved.toFixed(4),r.reached?'On target':'NR at cap'].join(','))].join('\n'),'text/csv')};
$('#summaryBtn').onclick=()=>{const a=data()[state.selected],s=withdrawalStats(a);download('ddr4d-scenario-summary.txt',`DDR4D scenario summary\n\nTechnology: ${state.technology}\nAdmin2: ${a.name}\nTarget: ${state.target}% active adoption\nDeadline: ${state.deadline} months\nEligibility: ${state.eligibility}%\nMinimum ToTs: ${a.tots}\nTrainer intensity: ${a.intensity.toFixed(2)} per 1,000 eligible farmers\nWithdrawal month: ${state.withdraw}\nFollow-up horizon: ${state.horizon} months\nTarget maintained: ${s.maint?'Yes':'No'}\nR_A: ${s.ra.toFixed(2)}\nNo-ToT equilibrium x*: ${pct(s.eq)}\n\nPROTOTYPE: Parameter values are provisional scenario inputs, not validated forecasts.`)};
$$('.tabs button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$$('[data-jump]').forEach(b=>b.onclick=()=>showTab(b.dataset.jump));function showTab(id){$$('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));$$('.tab-panel').forEach(p=>p.classList.toggle('active',p.id===id));window.scrollTo({top:410,behavior:'smooth'})}
$('#technology').onchange=e=>{state.technology=e.target.value;render()};$('#target').oninput=e=>{state.target=+e.target.value;render()};$('#deadline').onchange=e=>{state.deadline=+e.target.value;render()};$('#eligibility').oninput=e=>{state.eligibility=+e.target.value;render()};$('#horizon').onchange=e=>{state.horizon=+e.target.value;render()};$('#withdrawMonth').oninput=e=>{state.withdraw=+e.target.value;render()};$('#metric').onchange=e=>{state.metric=e.target.value;render()};$('#compartments').onchange=e=>{state.compartments=e.target.checked;render()};$$('th[data-sort]').forEach(th=>th.onclick=()=>{const k=th.dataset.sort;state.dir=state.sort===k?-state.dir:1;state.sort=k;render()});render();
